local koNG=CC.koNG-- (a jymain local in 3.0; exported as CC.koNG)
-- ko 3.0: 기록·도감. Counters live in the save's spare event flags (JY.Base 事件 n, signed 16-bit; events use ~1100,
-- 1994..1999 are cost/gold/cycle counters):
--   1101 패배   1102 총 턴   1104 격파(전체)   1105/1106 일기토 승/패   1107+1108x10000 얻은 금   1109+1110x10000 플레이 초
--   1111/1112/1113 이번 회차 턴/격파/승리      1120+(n-1)*4.. 회차 n 이력 {난이도 등급, 승리, 턴, 격파} (n=1..20)
--   1200+pid 무장별 격파 (pid 1..601)          1810+floor(c/15) bit c%15: 해금된 무장 (도감, c = koRecBook id), 1840+floor(c/15): 한 번이라도 아군이 된 무장
-- koNG.reset carries 1101..1870 into the next cycle (patch), writing the finished cycle's row first.
local koEV="\202\194\188\254"
function koRec(i) return JY.Base[koEV..i] or 0 end
function koRecSet(i,v) JY.Base[koEV..i]=v end
function koRecAdd(i,n) JY.Base[koEV..i]=math.min(koRec(i)+(n or 1),32767) end
-- two-field number: lo (0..9999) + hi x 10000
function koRecBig(i) return koRec(i)+koRec(i+1)*10000 end
function koRecBigAdd(i,n)
local v=koRecBig(i)+n
if v<0 then v=0 end
if v>327670000 then v=327670000 end
koRecSet(i,v%10000) koRecSet(i+1,math.floor(v/10000))
end
