-- (kept in CC: the strict _G metatable rejects a global that starts out nil)
function koRecCanonOf(id)
if CC.koRecCanon==nil then
CC.koRecCanon={}
CC.koRecByName={}
for _,b in ipairs(koRecBook) do
local nm=JY.Person[b]["\208\213\195\251"]
if CC.koRecByName[nm]==nil then CC.koRecByName[nm]=b end
end
for i=1,JY.PersonNum-1 do
CC.koRecCanon[i]=CC.koRecByName[JY.Person[i]["\208\213\195\251"]] or 0
end
end
return CC.koRecCanon[id] or 0
end
local function koRecBit(base,c) return base+math.floor(c/15),2^(c%15) end
local function koRecSetBit(base,c)
local f,bit=koRecBit(base,c)
local v=koRec(f)
if math.floor(v/bit)%2==0 then koRecSet(f,v+bit) end
end
local function koRecGetBit(base,c)
local f,bit=koRecBit(base,c)
return math.floor(koRec(f)/bit)%2==1
end
-- unlocked (offered by the tavern, or joined): the entry opens and stays open
function koRecUnlock(c) if c>0 then koRecSetBit(1810,c) end end
function koRecUnlocked(c) return koRecGetBit(1810,c) end
-- joined the roster at some point
function koRecMeet(id)
local c=koRecCanonOf(id)
if c<=0 then return end
koRecSetBit(1810,c) koRecSetBit(1840,c)
end
function koRecMet(c) return koRecGetBit(1840,c) end
-- ko 5.0: one of the hidden ones (??? until the tavern has offered him once: bit 1810, koRecSeen; town addon may redefine 해금)
function koRecSeen(c) return koRecGetBit(1810,c) end
function koRecHidden(c) return koRecSecret[c] and not koRecSeen(c) end
-- name sort key in 가나다 order: the hz codes are mapped to unicode through hzmb.dat (6-byte records: code(2) ?(2) unicode LE(2))
function koRecNameKey(nm)
CC.koRecNK=CC.koRecNK or {}
local k=CC.koRecNK[nm]
if k then return k end
if CC.koHzU==nil then
CC.koHzU={}
local h=io.open(CONFIG.CurrentPath.."hzmb.dat","rb")
if h then
local d=h:read("*a") h:close()
for i=1,#d-5,6 do
local key=string.byte(d,i)*256+string.byte(d,i+1)
if CC.koHzU[key]==nil then CC.koHzU[key]=string.byte(d,i+4)+string.byte(d,i+5)*256 end
end
