-- generals the tavern would offer right now (HirePerson's tables and gates, exported by the patch as koHireTables)
function koRecAvail()
local avail={}
koRecCanonOf(1)-- builds CC.koRecByName
local ok,db,db2,db3=pcall(koHireTables)
if not ok or type(db)~="table" then return avail end
for i,v in pairs(db) do
local c=0
if type(v)=="number" then c=koRecCanonOf(v) else c=CC.koRecByName[v] or 0 end
-- the same extra gates as the tavern (여포 = slot 442 / 주유 = 464: tournament wins / free battle wins), so the 도감
-- never opens someone the tavern is still hiding
local gate=not koHook("tavern_slot_lock",420+i)-- the same lock the tavern applies (여포 442, 주유 464 ...)
if c>0 and gate and (db2[i] or 9999)<JY.EventID then avail[c]=true end
end
for _,x in ipairs(rawget(_G,"koExtraHire") or {}) do-- 3.6: new tavern generals with their own records
if JY.EventID>x[2] and koExtraReq(x) then local c=koRecCanonOf(x[1]) if c>0 then avail[c]=true end end
end
for k,v in pairs(db3 or {}) do
local show,lock
if type(rawget(_G,"koTourGate"))=="function" then show,lock=koTourGate(v,k) else show=koStreakOK(k) lock=false end
if show and not lock then
local c=koRecCanonOf(v)
if c>0 then avail[c]=true end
end
end
return avail
end
