-- Tile the original menu artwork without scaling its pixel pattern or borders.
local function classicSegments(p,len,ilen,ins)
if len<=ilen then
local half=math.floor(len/2)
return {{p,p+half,p},{p+half,p+len,p+len-ilen}}
end
local step=math.floor((ilen-2*ins)/2)*2
local t={{p,p+ilen-ins,p}}
local last=p+ilen-ins
local finish=p+len-ilen+ins
for k=1,60 do
if last>=finish then break end
local q=p+k*step
local edge=math.min(q+ilen-ins,finish)
if edge>last then t[#t+1]={last,edge,q} last=edge end
end
t[#t+1]={finish,p+len,p+len-ilen}
return t
end
local function koClassicFrame(x,y,w,h)
for _,a in ipairs(classicSegments(x,w,382,8)) do
for _,b in ipairs(classicSegments(y,h,126,8)) do
if a[2]>a[1] and b[2]>b[1] then
lib.SetClip(a[1],b[1],a[2],b[2])
lib.PicLoadCache(4,50*2,a[3],b[3],1)
end
end
end
lib.SetClip(0,0,0,0)
end
local function koClassicBar(x,y,w,pressed)
local pic=(pressed and 62 or 61)*2
for _,a in ipairs(classicSegments(x,w,130,2)) do
if a[2]>a[1] then
lib.SetClip(a[1],y,a[2],y+22)
lib.PicLoadCache(4,pic,a[3],y,1)
end
end
lib.SetClip(0,0,0,0)
end
