-- the game's 무장 정보 panel for the entry, shown at level 99: the record is patched for the call and put back
-- (PersonStatus_sub runs ReSetAttrib, which rewrites 병력·공격·방어·장비 fields)
local function detail(c)
local p=JY.Person[c]
local snap={}
for k,v in pairs(CC.Person_S) do if v[4] then snap[k]=p[k] end end-- ko 3.6 later: stored fields only (writing back a newgame-only field would wipe the MVP / 전적 counts kept in its save bytes)
p["\181\200\188\182"]=99 p["\190\173\209\233"]=0-- 等级 经验
local ok,err=pcall(PersonStatus,c,nil,nil,2)
for k,v in pairs(snap) do p[k]=v end
if not ok then lib.Debug("koRecord detail: "..tostring(err)) end
end
-- locked entry: the game's 무장 정보 panel with the face hidden, the class masked and the right column replaced by
-- the unlock conditions (등용무장 목록 line + progress; 유방·항우: the tavern's four O/X conditions)
local function hint(c)
local h=koRecHint[c] or ""
local bz,cond=string.match(h,"^(.-)\t(.*)$")-- tab-separated: "|" (124) can be the second byte of a hz code (초)
-- 5.2.5 (10-20, 카페 제보 「이숙 술집 단병 / 도감 궁병」): the list's class is the one before spriteclass; a general given a
-- 성삼국 sprite shows the class spriteclass moves him to (the same tier), as the tavern copy has it
local sk,sf=rawget(_G,"koSpriteKind"),rawget(_G,"koSpriteFit")
if bz and bz~="" and sk and sf and sk[c] then
for id=1,JY.BingzhongNum-1 do
if JY.Bingzhong[id]["\195\251\179\198"]==bz then
if id~=21 or c==95 or c==208 or c==209 or c==112 then bz=JY.Bingzhong[sf(sk[c],id)]["\195\251\179\198"] end-- a catapult keeps it (spriteclass FORCE21)
break
end
end
end
local p=JY.Person[c]
local nm=koRecHidden(c) and "???" or p[NAME]
-- the condition text, '*' = new line (DrawStr wraps at 16 chars)
local t
if (c==407 or c==408 or c==409) and type(rawget(_G,"koUnlockText"))=="function" then
t=koUnlockText(c)
else
t="\133\125\132\111 \129\118\129\119"-- 등용 조건
if cond and cond~="" then t=t.."*"..cond end
if cond then
local prog={}
local n=string.match(cond,"\133\066\130\066 (%d+)\130\125")
if n then-- ko 4.0 later: 연전 N회 -> 술 겨루기 N번째 X 이기기 (the stage by person: 목인·호적's hint text still says 12)
local ds,dc,lr=rawget(_G,"koDrinkStage"),rawget(_G,"koDrinkCond"),rawget(_G,"koLlkRec")-- drink addon (may be off; strict _G)
local st=(ds and ds[c]) or tonumber(n)
if dc then local r=dc(st,true) t=string.gsub(t,"\133\066\130\066 "..n.."\130\125",function() return r end,1) end
prog[#prog+1]="\131\072 \132\125\131\094\131\071 \131\071\133\108 "..math.min(JY.Base[koEV.."333"] or 0,st).."/"..st-- 술 겨루기 기록 x/N
if lr then prog[#prog+1]="\130\114\130\115\131\123 "..math.min(lr(),st).."/"..st end-- ko 5.0: 사천성 y/N (the other way in)
end
n=string.match(cond,"\131\079\129\116 (%d+)\130\125")
if n then prog[#prog+1]="\131\079\129\116 "..math.min(koRec(1971),tonumber(n)).."/"..n end
n=string.match(cond,"4\130\073 (%d+)\130\125")
if n then prog[#prog+1]="4\130\073 "..math.min(koRec(1972),tonumber(n)).."/"..n end
n=string.match(cond,"\133\120\130\071 \130\066\132\101 \129\116\129\117 (%d+)\130\125")-- 자유 전투 승리 N회 (ko_settings, not the save)
if n then prog[#prog+1]="\133\120\130\071 \130\066\132\101 "..math.min(CC.koFreeWin or 0,tonumber(n)).."/"..n end
if #prog>0 then t=t.."*\129\103\130\093 "..table.concat(prog,"  ") end-- 진행
end
end
-- ko 5.0: a tavern general — 연고 and the 주점 towns by chapter (town addon; not for the hidden three while locked)
if rawget(_G,"koTavernWhereText") and not koRecHidden(c) then local w=koTavernWhereText(c,t) if w then t=w end end-- ko 5.0: 【출현 조건】 / 【연고】
-- the panel at PersonStatus's city position; stats as in PersonStatus_sub (Enhancement layout), level 99
local x,y=16+(640-456)/2,16+(400-276)/2
local snap={}
for k,v in pairs(CC.Person_S) do if v[4] then snap[k]=p[k] end end-- ko 3.6 later: stored fields only (writing back a newgame-only field would wipe the MVP / 전적 counts kept in its save bytes)
p["\181\200\188\182"]=99 p["\190\173\209\233"]=0-- 等级 经验
local ok,err=pcall(ReSetAttrib,c,false)
if not ok then lib.Debug("koRecord hint: "..tostring(err)) end
local function panel()
lib.PicLoadCache(4,85*2,x,y,1)
DrawString(x+135-#nm*16/4,y+20,nm,M_White,16)
local bzname=(bz and bz~="") and bz or JY.Bingzhong[p["\177\248\214\214"]]["\195\251\179\198"]-- 병종 from the list (else the record's)
DrawString(x+184,y+20,bzname,M_White,16)
lib.PicLoadCache(2,((rawget(_G,"koBookShowFace") and koBookShowFace(c)) or 1239)*2,x+24,y+24,1)
DrawString(x+129,y+65,"?",M_White,32)-- the unit sprite frame (black 50x50 at x+111,y+55): a big question mark, ink centred
lib.PicLoadCache(4,55*2,x+384,y+16,1)-- 확인
lib.FillColor(x+180,y+48,x+448,y+266,RGB(8,12,48))-- covers the 천부 box, the numbers and the item frame
lib.DrawRect(x+180,y+48,x+448,y+48,M_Gray) lib.DrawRect(x+180,y+266,x+448,y+266,M_Gray)
lib.DrawRect(x+180,y+48,x+180,y+266,M_Gray) lib.DrawRect(x+448,y+48,x+448,y+266,M_Gray)
lib.SetClip(x+180,y+48,x+448,y+266)
DrawStr(x+184,y+56,GenTalkString(t,16),M_White,16)
lib.SetClip(0,0,0,0)
local len=100
local kolen=koNG.cap()
if kolen<100 then kolen=100 end
for i,v in pairs({"\206\228\193\166","\214\199\193\166","\205\179\194\202"}) do-- 武力 智力 统率
local v1=p[v.."2"]
local color=(v1<30) and 210 or ((v1<70) and 211 or 212)
