lib.PicLoadCache(4,color*2,x+44,y+87+i*32,1)
lib.SetClip(0,0,0,0)
local str=string.format("%d",v1)
DrawString2(x+44+60-16*#str/4,y+87-3+i*32,str,M_White,16)
lib.FillColor(x+44,y+103+i*32,x+44+len,y+103+10+i*32,M_Black)-- the experience bar row, empty
end
if CC.Enhancement then
DrawString(x+16,y+220,"\131\071\131\072",M_White,16)-- 기술
for i=1,6 do-- the skill table as DrawSkillTable draws it, every cell ？？
local cx,cy=x+56+36*((i-1)%3),y+220+20*math.modf((i-1)/3)
lib.DrawRect(cx,cy,cx+36,cy,M_White) lib.DrawRect(cx,cy+20,cx+36,cy+20,M_White)
