lib.Background(cx+1,cy+1,cx+36,cy+20,240,M_Blue)
do local koSk=rawget(_G,"koBookSkill") and koBookSkill(c,i) if koSk then DrawString(cx+2,cy+2,koSk,M_White,16) else DrawString(cx+2,cy+2,"\163\191\163\191",M_Gray,16) end end--ko 11-11: the merged book shows an unlocked officer's skills
end
end
end
local function draw(hov)
panel()
end
koTourWait(draw,{{x=x+384,y=y+16,w=52,h=24,s="",plain=true}})
for k,v in pairs(snap) do p[k]=v end
end
local function draw(hov)
back()
if extra() then extra().draw(page,{ox=ox,oy=oy,cx=cx,txt=txt,ctext=ctext,rtext=rtext})
ctext(oy+445,page.." / "..math.max(1,math.ceil(rowsOf()/perOf())),M_Gray)
elseif tab==1 then drawStats() elseif tab==2 then drawHistory() elseif tab==3 then drawRank() else drawBook(hov)
end
end
local function overlay(hov)
if hov and btns[hov] and btns[hov].xtab and extra() and extra().tip then extra().tip(btns[hov],{ox=ox,oy=oy,cx=cx,txt=txt,ctext=ctext,rtext=rtext}) end--ko 5.0 (10-13)
if hov and btns[hov] and btns[hov].pid and rawget(_G,"koTavernTip") then koTavernTip(btns[hov].pid,btns[hov].x,btns[hov].y,true,koClassicFrame) end
end
do local koF=rawget(_G,"koBookFocus") if koF then rawset(_G,"koBookFocus",nil) if JY.Person[koF] then if koRecUnlocked(koF) then detail(koF) else hint(koF) end end if rawget(_G,"koBookFocusOnly") then return end end end--ko 11-11: opened for one officer (another story's, after the switch); FocusOnly = that panel alone
while true do
buildbtns()
local r=koTourWait(draw,btns,overlay)
if r==0 or r==1 then break end
if btns[r] and btns[r].tabid then
if tab~=btns[r].tabid then tab=btns[r].tabid page=1 end
elseif btns[r] and btns[r].grpbtn then
group=3-group page=1
for t=FIRSTTAB,NT do if ((t>4 and koRecGroup[koRecTabs[t-4].label]) and 2 or 1)==group then tab=t break end end
elseif btns[r] and btns[r].filt then
filt=btns[r].filt page=1 rebuild()
elseif btns[r] and btns[r].sortk then
sortk=btns[r].sortk page=1 rebuild()
elseif btns[r] and btns[r].xtab then
if extra() and extra().click then extra().click(btns[r]) end
elseif btns[r] and btns[r].plain and rawget(_G,"koBookForeign") and koBookForeign(btns[r].pid) then hint(btns[r].pid)--ko 11-11: an officer the loaded story does not have: the condition panel from the merged data
elseif btns[r] and btns[r].plain then
if koRecUnlocked(btns[r].pid) then detail(btns[r].pid)
else hint(btns[r].pid) end
MOUSE.koSwallowR=true MOUSE.status='IDLE'-- ko 5.0: the 무장 정보 panel reads the right click that closes it straight from the device; its queued press must not close the record screen too
elseif btns[r] and btns[r].s==S_PREV then
if page>1 then page=page-1 end
elseif btns[r] and btns[r].s==S_NEXT then
if page<math.ceil(rowsOf()/perOf()) then page=page+1 end
end
end
end


